<?php $locked = $c && $c['status'] !== 'draft'; $seg = $c ? json_dec($c['segment']) : []; ?>
<?php if ($stats): ?><div class="stats"><div class="stat"><b><?= (int) $stats['total'] ?></b><span>Recipients</span></div><div class="stat"><b><?= (int) $stats['sent'] ?></b><span>Delivered to server</span></div><div class="stat"><b><?= (int) $stats['opened'] ?></b><span>Opened (<?= $stats['total'] ? round($stats['opened'] * 100 / $stats['total']) : 0 ?>%)</span></div><div class="stat"><b><?= (int) $stats['clicked'] ?></b><span>Clicked</span></div><div class="stat <?= $stats['failed'] ? 'alert' : '' ?>"><b><?= (int) $stats['failed'] ?></b><span>Failed</span></div><div class="stat"><b><?= (int) $stats['queued'] ?></b><span>Still queued</span></div></div>
<p class="muted xs">Open tracking relies on images and is approximate; some mail apps pre-load or block them.</p><?php endif; ?>
<div class="two"><form class="panel" method="post" action="/admin/campaigns/save"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) ($c['id'] ?? 0) ?>"><div class="panel-h"><?= $locked ? 'Campaign (locked)' : 'Compose' ?> <?= $c ? badge($c['status']) : '' ?></div><div class="panel-b form">
  <fieldset <?= $locked ? 'disabled' : '' ?> style="border:0;padding:0;margin:0;display:grid;gap:16px">
  <div class="row2"><?= a_in('Internal name', 'name', $c['name'] ?? '', ['required' => true]) ?><?= a_sel('Send from', 'mailbox', array_column($boxes, 'display_name', 'address'), $c['mailbox'] ?? 'info@' . cfg('domain')) ?></div>
  <?= a_in('Subject line', 'subject', $c['subject'] ?? '', ['required' => true]) ?><?= a_in('Preview text', 'preheader', $c['preheader'] ?? '', ['hint' => 'The short summary shown next to the subject in many inboxes.']) ?>
  <div class="row2"><?= a_sel('Audience', 'segment', $segments, $seg['type'] ?? 'all') ?><?= a_in('Tag (for “specific tag”)', 'tag', $seg['tag'] ?? '') ?></div>
  <div class="field"><label>Message</label><div class="rte"><div class="rte-bar"><button type="button" data-cmd="bold"><b>B</b></button><button type="button" data-cmd="italic"><i>I</i></button><button type="button" data-cmd="insertUnorderedList">• List</button><button type="button" data-cmd="formatBlock" data-val="h2">Heading</button><button type="button" id="rteLink">Link</button><button type="button" id="mergeBtn">Insert first name</button></div><div class="rte-area" id="rte" contenteditable="<?= $locked ? 'false' : 'true' ?>"><?= $c['body'] ?? '<p>Hello {{first_name}},</p><p></p>' ?></div></div><textarea name="body" id="bodyField" hidden></textarea><span class="hint">Merge tags: {{first_name}}, {{name}}. An unsubscribe link is added automatically.</span></div>
  <?= a_in('Schedule for (optional)', 'scheduled_at', $c && $c['scheduled_at'] ? date('Y-m-d\TH:i', strtotime($c['scheduled_at'])) : '', ['type' => 'datetime-local']) ?>
  </fieldset>
  <?php if (!$locked): ?><div><button class="btn btn-primary btn-sm">Save draft</button></div><?php endif; ?></div></form>
<div>
  <?php if ($c && !$locked): ?><div class="panel"><div class="panel-h">Send</div><div class="panel-b"><p class="small">This audience currently has <strong><?= (int) $audience ?></strong> subscribed contact(s).</p>
    <form method="post" action="/admin/campaigns/<?= (int) $c['id'] ?>/test" style="margin-bottom:10px"><?= csrf_field() ?><button class="btn btn-ghost btn-sm">Send a test to me</button></form>
    <form method="post" action="/admin/campaigns/<?= (int) $c['id'] ?>/launch"><?= csrf_field() ?><button class="btn btn-primary btn-sm" data-confirm="Queue this campaign for <?= (int) $audience ?> recipient(s)? You cannot edit it afterwards.">Launch campaign</button></form></div></div><?php endif; ?>
  <?php if ($c && $c['status'] === 'sending'): ?><div class="panel"><div class="panel-b"><form method="post" action="/admin/campaigns/<?= (int) $c['id'] ?>/pause"><?= csrf_field() ?><button class="btn btn-danger btn-sm" data-confirm="Stop sending the remaining messages?">Stop sending</button></form></div></div><?php endif; ?>
  <?php if ($recips): ?><div class="panel"><div class="panel-h">Recipients</div><div class="table-wrap" style="border:0;max-height:420px;overflow:auto"><table class="t"><tbody><?php foreach ($recips as $r): ?><tr><td><?= e($r['email']) ?></td><td><?= badge($r['status'], ['sent' => 'green', 'failed' => 'red'][$r['status']] ?? '') ?></td><td class="xs muted"><?= $r['open_count'] ? '👁 ' . (int) $r['open_count'] : '' ?> <?= $r['click_count'] ? '🖱 ' . (int) $r['click_count'] : '' ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php endif; ?>
</div></div>
<script>(function(){var r=document.getElementById('rte'),f=document.querySelector('form[action="/admin/campaigns/save"]'),b=document.getElementById('bodyField');if(!f)return;
document.querySelectorAll('[data-cmd]').forEach(function(x){x.addEventListener('mousedown',function(e){e.preventDefault()});x.addEventListener('click',function(){document.execCommand(x.dataset.cmd,false,x.dataset.val||null);r.focus()})});
document.getElementById('rteLink').addEventListener('click',function(){var u=prompt('Link address (https://…)');if(u&&/^https?:\/\//i.test(u))document.execCommand('createLink',false,u)});
document.getElementById('mergeBtn').addEventListener('click',function(){r.focus();document.execCommand('insertText',false,'{{first_name}}')});
f.addEventListener('submit',function(){b.value=r.innerHTML})})();</script>
